#include "editor/SubspaceEditorLayoutSystem.h"
#include <algorithm>
namespace subspace {
EditorWorkspaceLayout SubspaceEditorLayoutSystem::Build(int w,int h,bool showOutliner,bool showBottom){EditorWorkspaceLayout o;o.viewportWidth=std::max(640,w);o.viewportHeight=std::max(420,h);o.leftWidth=std::clamp(float(o.viewportWidth)*.18f,240.0f,360.0f);o.rightWidth=std::clamp(float(o.viewportWidth)*.20f,280.0f,400.0f);o.bottomHeight=showBottom?std::clamp(float(o.viewportHeight)*.22f,130.0f,240.0f):0.0f;const float contentY=o.topBarHeight;const float contentH=float(o.viewportHeight)-contentY-o.bottomHeight;const float centerX=o.leftWidth;const float centerW=float(o.viewportWidth)-o.leftWidth-o.rightWidth;o.panels.push_back({EditorPanelSlot::AssetBrowser,"asset_browser",0,contentY,o.leftWidth,contentH,true,true});o.panels.push_back({EditorPanelSlot::Viewport,"viewport",centerX,contentY,centerW,contentH,true,false});o.panels.push_back({EditorPanelSlot::Inspector,"inspector",centerX+centerW,contentY,o.rightWidth,contentH,true,true});if(showOutliner)o.panels.push_back({EditorPanelSlot::Outliner,"outliner",centerX+centerW,contentY,o.rightWidth,std::min(240.0f,contentH*.34f),true,true});if(showBottom){o.panels.push_back({EditorPanelSlot::Validation,"validation",centerX,float(o.viewportHeight)-o.bottomHeight,centerW,o.bottomHeight,true,true});}return o;}
bool SubspaceEditorLayoutSystem::Validate(const EditorWorkspaceLayout&o,std::string*error){if(o.viewportWidth<640||o.viewportHeight<420){if(error)*error="editor viewport below minimum supported dimensions";return false;}for(const auto&p:o.panels){if(!p.visible)continue;if(p.width<=0||p.height<=0||p.x<0||p.y<0||p.x+p.width>o.viewportWidth+.01f||p.y+p.height>o.viewportHeight+.01f){if(error)*error="editor panel lies outside workspace bounds: "+p.id;return false;}}return true;}
} // namespace subspace
